import sqlite3
from typing import List, Dict, Any, Tuple

# --- Required external deps ---
# pip install pymilvus sentence-transformers
from pymilvus import connections, Collection
from sentence_transformers import SentenceTransformer


# -------------------------------
# Fixed configuration (as required)
# -------------------------------
sqlite_paths = {
    "business": "D:/Yelp-JSON/db/sqlite3/business.db",
    "checkin": "D:/Yelp-JSON/db/sqlite3/checkin.db",
    "photo": "D:/Yelp-JSON/db/sqlite3/photo.db",
    "review": "D:/Yelp-JSON/db/sqlite3/review.db",
    "tip": "D:/Yelp-JSON/db/sqlite3/tip.db",
    "user": "D:/Yelp-JSON/db/sqlite3/user.db"
}

milvus_config = {
    'milvus_collections': {
        'reviews': 'reviews',
        'photos': 'photo_vector',
        'tips': 'milvus_tip'
    },
    'milvus_host': 'localhost',
    'milvus_port': '19530'
}

neo4j_config = {
    'neo4j_uri': 'bolt://localhost:7687',
    'neo4j_auth': ('neo4j', 'password')
}


def chunked(lst: List[Any], size: int = 200) -> List[List[Any]]:
    return [lst[i:i + size] for i in range(0, len(lst), size)]


def sql_in_clause(n: int) -> str:
    return "(" + ",".join(["?"] * n) + ")"


def connect_sqlite(path: str) -> sqlite3.Connection:
    conn = sqlite3.connect(path)
    conn.row_factory = sqlite3.Row
    return conn


def get_candidate_businesses(city: str = "Tampa") -> List[Dict[str, Any]]:
    conn = connect_sqlite(sqlite_paths["business"])
    try:
        q = """
        SELECT business_id, name, stars, address, city, state, postal_code, categories
        FROM business
        WHERE city = ?
          AND categories LIKE '%Mexican%'
          AND categories LIKE '%Restaurant%'
        """
        rows = conn.execute(q, (city,)).fetchall()
        return [dict(r) for r in rows]
    finally:
        conn.close()


def init_milvus() -> None:
    connections.connect(
        alias="default",
        host=milvus_config['milvus_host'],
        port=milvus_config['milvus_port']
    )


def embed_text(model: SentenceTransformer, text: str) -> List[float]:
    v = model.encode([text], normalize_embeddings=True)
    return v[0].tolist()


def milvus_search_by_business_chunks(
    collection_name: str,
    query_vec: List[float],
    business_ids: List[str],
    topk_per_chunk: int = 50,
    output_fields: List[str] = None,
    vector_field: str = "embedding",
    business_field: str = "business_id",
) -> List[Dict[str, Any]]:
    """Search Milvus with expr business_id in [...] chunked to avoid overly long expressions."""
    if output_fields is None:
        output_fields = [business_field]

    col = Collection(collection_name)
    col.load()

    hits_all: List[Dict[str, Any]] = []
    for chunk in chunked(business_ids, size=200):
        # Build Milvus expr. If business_id is stored as VARCHAR, quotes are needed.
        # We'll quote as strings.
        quoted = ",".join([f'"{bid}"' for bid in chunk])
        expr = f"{business_field} in [{quoted}]"

        res = col.search(
            data=[query_vec],
            anns_field=vector_field,
            param={"metric_type": "IP", "params": {"nprobe": 16}},
            limit=topk_per_chunk,
            expr=expr,
            output_fields=output_fields,
            consistency_level="Strong"
        )
        # res is a list (per query). We used one query.
        for hit in res[0]:
            entity = {}
            # output fields
            for f in output_fields:
                try:
                    entity[f] = hit.entity.get(f)
                except Exception:
                    entity[f] = None
            entity["score"] = float(hit.score)
            hits_all.append(entity)

    return hits_all


def get_tip_hits_for_spicy_sauce(candidate_business_ids: List[str]) -> List[Dict[str, Any]]:
    """Vector-search tips for 'spicy sauce' within candidate business_ids."""
    init_milvus()
    model = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")
    qvec = embed_text(model, "spicy sauce")

    # Try to request common fields. Adjust if your collection uses different names.
    output_fields = ["business_id", "tip_id", "text"]
    return milvus_search_by_business_chunks(
        collection_name=milvus_config['milvus_collections']['tips'],
        query_vec=qvec,
        business_ids=candidate_business_ids,
        topk_per_chunk=50,
        output_fields=output_fields,
        vector_field="embedding",
        business_field="business_id",
    )


def get_business_details(business_ids: List[str]) -> Dict[str, Dict[str, Any]]:
    if not business_ids:
        return {}
    conn = connect_sqlite(sqlite_paths["business"])
    try:
        out: Dict[str, Dict[str, Any]] = {}
        for chunk in chunked(business_ids, 900):
            q = f"""
            SELECT business_id, name, stars, address, city, state, postal_code
            FROM business
            WHERE business_id IN {sql_in_clause(len(chunk))}
            """
            rows = conn.execute(q, chunk).fetchall()
            for r in rows:
                d = dict(r)
                d["full_address"] = ", ".join([
                    d.get("address") or "",
                    d.get("city") or "",
                    d.get("state") or "",
                    d.get("postal_code") or ""
                ]).strip(", ")
                out[d["business_id"]] = d
        return out
    finally:
        conn.close()


def get_burrito_photos_via_milvus(matched_business_ids: List[str]) -> List[Dict[str, Any]]:
    init_milvus()
    model = SentenceTransformer("sentence-transformers/all-MiniLM-L6-v2")
    qvec = embed_text(model, "burrito")

    output_fields = ["business_id", "photo_id"]
    return milvus_search_by_business_chunks(
        collection_name=milvus_config['milvus_collections']['photos'],
        query_vec=qvec,
        business_ids=matched_business_ids,
        topk_per_chunk=200,
        output_fields=output_fields,
        vector_field="embedding",
        business_field="business_id",
    )


def get_burrito_photos_fallback_sql(matched_business_ids: List[str]) -> List[Dict[str, Any]]:
    if not matched_business_ids:
        return []
    conn = connect_sqlite(sqlite_paths["photo"])
    try:
        results: List[Dict[str, Any]] = []
        for chunk in chunked(matched_business_ids, 900):
            q = f"""
            SELECT photo_id, business_id, caption, label
            FROM photo
            WHERE business_id IN {sql_in_clause(len(chunk))}
              AND (caption LIKE '%burrito%' OR caption LIKE '%Burrito%')
            """
            rows = conn.execute(q, chunk).fetchall()
            results.extend([dict(r) for r in rows])
        return results
    finally:
        conn.close()


def get_reviews_with_authors(business_ids: List[str], per_business: int = 3) -> Dict[str, List[Dict[str, Any]]]:
    if not business_ids:
        return {}

    rconn = connect_sqlite(sqlite_paths["review"])
    uconn = connect_sqlite(sqlite_paths["user"])

    try:
        out: Dict[str, List[Dict[str, Any]]] = {bid: [] for bid in business_ids}

        # Build a temp map of user_id -> name for only referenced users (two-pass)
        review_rows: List[sqlite3.Row] = []
        for chunk in chunked(business_ids, 800):
            q = f"""
            SELECT business_id, review_id, user_id, stars AS review_stars, date
            FROM review
            WHERE business_id IN {sql_in_clause(len(chunk))}
            ORDER BY date DESC
            """
            review_rows.extend(rconn.execute(q, chunk).fetchall())

        # Keep only top N per business
        picked: List[Dict[str, Any]] = []
        counts: Dict[str, int] = {bid: 0 for bid in business_ids}
        user_ids: set = set()
        for r in review_rows:
            bid = r["business_id"]
            if bid not in counts:
                continue
            if counts[bid] >= per_business:
                continue
            d = dict(r)
            picked.append(d)
            counts[bid] += 1
            if d.get("user_id"):
                user_ids.add(d["user_id"])

        user_map: Dict[str, str] = {}
        if user_ids:
            user_ids_list = list(user_ids)
            for chunk in chunked(user_ids_list, 900):
                q = f"SELECT user_id, name FROM user WHERE user_id IN {sql_in_clause(len(chunk))}"
                for ur in uconn.execute(q, chunk).fetchall():
                    user_map[ur["user_id"]] = ur["name"]

        for d in picked:
            bid = d["business_id"]
            d["author"] = user_map.get(d.get("user_id"), None)
            out.setdefault(bid, []).append(d)

        return out
    finally:
        rconn.close()
        uconn.close()


def main():
    # 1) Candidate Tampa Mexican restaurants (SQLite)
    candidates = get_candidate_businesses(city="Tampa")
    candidate_ids = [c["business_id"] for c in candidates]

    if not candidate_ids:
        print({"results": [], "note": "No Tampa Mexican restaurants found in business.db"})
        return

    # 2) Tips vector search: 'spicy sauce' within candidates (Milvus)
    try:
        tip_hits = get_tip_hits_for_spicy_sauce(candidate_ids)
    except Exception as e:
        # If Milvus is unavailable, we cannot satisfy the 'tips mentioning spicy sauce' constraint reliably.
        raise RuntimeError(
            "Milvus tip vector search failed. Ensure Milvus is running and 'milvus_tip' exists with fields business_id/embedding."
        ) from e

    # Filter businesses by tip hit threshold (optional). Here: keep any hit.
    matched_ids = sorted({h.get("business_id") for h in tip_hits if h.get("business_id")})

    if not matched_ids:
        print({"results": [], "note": "No matched businesses after tip vector search for 'spicy sauce'."})
        return

    # 3) Business details (SQLite)
    biz_details = get_business_details(matched_ids)

    # 4) Burrito photos (Milvus with fallback to SQLite)
    photo_hits: List[Dict[str, Any]] = []
    try:
        photo_hits = get_burrito_photos_via_milvus(matched_ids)
    except Exception:
        photo_hits = []

    fallback_photos = []
    if not photo_hits:
        fallback_photos = get_burrito_photos_fallback_sql(matched_ids)

    # Index photos by business
    photos_by_biz: Dict[str, List[Dict[str, Any]]] = {bid: [] for bid in matched_ids}
    for p in photo_hits:
        bid = p.get("business_id")
        if not bid:
            continue
        photos_by_biz.setdefault(bid, []).append({
            "photo_id": p.get("photo_id"),
            "score": p.get("score")
        })

    for p in fallback_photos:
        bid = p.get("business_id")
        photos_by_biz.setdefault(bid, []).append({
            "photo_id": p.get("photo_id"),
            "caption": p.get("caption"),
            "label": p.get("label"),
            "score": None
        })

    # 5) Reviews + authors (SQLite)
    reviews_by_biz = get_reviews_with_authors(matched_ids, per_business=3)

    # Also keep a few example tip hits per business as evidence
    tips_by_biz: Dict[str, List[Dict[str, Any]]] = {bid: [] for bid in matched_ids}
    for h in sorted(tip_hits, key=lambda x: x.get("score", 0.0), reverse=True):
        bid = h.get("business_id")
        if not bid:
            continue
        if len(tips_by_biz.setdefault(bid, [])) >= 3:
            continue
        tips_by_biz[bid].append({
            "tip_id": h.get("tip_id"),
            "text": h.get("text"),
            "score": h.get("score")
        })

    # 6) Final aggregation
    results = []
    for bid in matched_ids:
        b = biz_details.get(bid, {"business_id": bid})
        results.append({
            "business_id": bid,
            "name": b.get("name"),
            "address": b.get("full_address") or b.get("address"),
            "business_rating_stars": b.get("stars"),
            "tip_evidence": tips_by_biz.get(bid, []),
            "burrito_photos": photos_by_biz.get(bid, [])[:10],
            "recent_reviews": reviews_by_biz.get(bid, [])
        })

    # Sort: prefer higher business stars, then more photos
    results.sort(key=lambda x: ((x.get("business_rating_stars") or 0), len(x.get("burrito_photos") or [])), reverse=True)

    print({
        "city": "Tampa",
        "query": {
            "category": "Mexican restaurants",
            "tip_semantic": "spicy sauce",
            "photo_semantic": "burrito"
        },
        "count": len(results),
        "results": results
    })


if __name__ == "__main__":
    main()

